    Since Python 3.9, descriptors like property can be wrapped by
    @classmethod and @staticmethod. In that case, accessing the
    attribute may return the computed value instead of the descriptor.
    Try to unwrap known wrappers to detect the underlying descriptor.
    """
    # Fast path for plain/cached properties
    if sys.version_info >= (3, 8):
        from functools import cached_property
        if isinstance(obj, cached_property):
            return True
    if isinstance(obj, property):
        return True

    # Check wrapped descriptors (classmethod/staticmethod) and other wrappers
    unwrapped = unwrap_all(obj)
    try:
        if isinstance(unwrapped, property):
            return True
        if sys.version_info >= (3, 8):
            from functools import cached_property
            if isinstance(unwrapped, cached_property):
                return True
    except Exception:
        pass

    # Peek into common wrapper attributes as a fallback
    target = getattr(obj, '__wrapped__', None) or getattr(obj, '__func__', None)
    if target is not None:
        try:
            if isinstance(target, property):
                return True
        except Exception:
            pass

    return False'''

