        # Import the object using the base logic first
        ret = super().import_object(raiseerror)
        if not ret:
            return ret
        # Prefer the raw descriptor stored on the class dict
        obj = getattr(self.parent, '__dict__', {}).get(self.object_name, self.object)
        # Unwrap classmethod/staticmethod and other wrappers
        try:
            unwrapped = inspect.unwrap_all(obj)
        except Exception:
            unwrapped = obj
        target = None
        if isinstance(obj, property):
            target = obj
        elif isinstance(unwrapped, property):
            target = unwrapped
        else:
            inner = getattr(obj, '__wrapped__', None) or getattr(obj, '__func__', None)
            if isinstance(inner, property):
                target = inner
        if target is not None:
            self.object = target
        return ret'''

