int INTOFF = 9;
int LITSIZE = 4;

void pc(int c) {
  putchar(c + 1);
}

void put_bit(int bit, int ctx) {
  if (range < radix) {
    range *= radix;
    pc(fraction / radix);
    fraction %= radix;
  }

  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;
}

void put_integer(int val, int bits, int ctx) {
  val += (1 << bits);
  ctx *= 99;

  for (i = bits; i >= 0; i--) {
    put_bit((val >> i) & 1, ++tmp + ctx);
  }
  put_bit(1, ++tmp + ctx);
}

void flush() {
  while (range < radix) {
    range *= radix;
    pc(fraction / radix);
    fraction %= radix;
  }
}

