use crate::lzma_packet::{LZMAPacket, LZMAPacketType};
use crate::lzma_state::LZMAState;
use crate::substring_enumerator::SubstringEnumerator;

pub struct PacketEnumerator<'a> {
    /// A slice of input data.
    pub data: &'a [u8],
    /// An owned substring enumerator built on the same data.
    pub substring_enumerator: Box<SubstringEnumerator<'a>>,
}

impl<'a> PacketEnumerator<'a> {
    pub fn memory_usage(_data_size: usize) -> usize {
        // Simplified memory usage calculation
        std::mem::size_of::<PacketEnumerator>() + SubstringEnumerator::memory_usage(_data_size)
    }

    pub fn new(data: &'a [u8]) -> Self {
        let substring_enumerator = Box::new(SubstringEnumerator::new(data, 2, 273));
        Self {
            data,
            substring_enumerator,
        }
    }

    pub fn for_each<F>(&self, state: &LZMAState, mut callback: F)
    where
        F: FnMut(&LZMAState, LZMAPacket),
    {
        // Literal packet
        callback(state, LZMAPacket::literal_packet());

        // Short rep packet if possible
        if state.position > 0 {
            let rep0_position = state.position as i32 - state.dists[0] as i32 - 1;
            if rep0_position >= 0 && rep0_position < state.data.len() as i32 {
                if state.data[state.position] == state.data[rep0_position as usize] {
                    callback(state, LZMAPacket::short_rep_packet());
                }
            }
        }

        // Match and long rep packets via substring enumerator
        struct CallbackData<'a, F> where F: FnMut(&LZMAState, LZMAPacket) {
            state: &'a LZMAState,
            callback: F,
        }

        let mut callback_data = CallbackData {
            state,
            callback,
        };

        self.substring_enumerator.for_each(state.position, |offset, length| {
            let dist = state.position - offset - 1;
            callback_data.callback(callback_data.state, LZMAPacket::match_packet(dist as u32, length as u32));

            for i in 0..4 {
                if dist as u32 == callback_data.state.dists[i] {
                    callback_data.callback(callback_data.state, LZMAPacket::long_rep_packet(i as u32, length as u32));
                }
            }
        });
    }
}
